package com.personal.assistant.module.financeplanning.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.financeplanning.dto.FinancePlanningRequests.*;import com.personal.assistant.module.financeplanning.service.FinancePlanningService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/finance-planning")public class FinancePlanningController{private final FinancePlanningService service;public FinancePlanningController(FinancePlanningService service){this.service=service;}private Long uid(){return SecurityContextHelper.currentUserId();}@GetMapping("/budgets")public ApiResponse<List<Map<String,Object>>>budgets(@RequestParam(required=false)String periodKey){return ApiResponse.success(service.budgets(uid(),periodKey));}@PostMapping("/budgets")public ApiResponse<Long>budget(@Valid @RequestBody Budget r){return ApiResponse.success(service.saveBudget(uid(),r));}@GetMapping("/net-worth")public ApiResponse<List<Map<String,Object>>>snapshots(){return ApiResponse.success(service.snapshots(uid()));}@PostMapping("/net-worth")public ApiResponse<Long>snapshot(@Valid @RequestBody Snapshot r){return ApiResponse.success(service.saveSnapshot(uid(),r));}@PostMapping("/recurring/detect")public ApiResponse<Integer>detect(){return ApiResponse.success(service.detectRecurring(uid()));}@GetMapping("/recurring")public ApiResponse<List<Map<String,Object>>>recurring(){return ApiResponse.success(service.recurring(uid()));}@PostMapping("/anomalies/scan")public ApiResponse<Integer>scan(){return ApiResponse.success(service.scanAnomalies(uid()));}@GetMapping("/anomalies")public ApiResponse<List<Map<String,Object>>>anomalies(){return ApiResponse.success(service.anomalies(uid()));}@PostMapping("/reconciliations")public ApiResponse<Long>reconcile(@Valid @RequestBody Reconcile r){return ApiResponse.success(service.reconcile(uid(),r));}@GetMapping("/templates")public ApiResponse<List<Map<String,Object>>>templates(){return ApiResponse.success(service.templates(uid()));}@PostMapping("/templates")public ApiResponse<Long>template(@Valid @RequestBody Template r){return ApiResponse.success(service.saveTemplate(uid(),r));}@PatchMapping("/raw-rows/{id}")public ApiResponse<Void>repair(@PathVariable Long id,@Valid @RequestBody RawRepair r){service.repairRaw(uid(),id,r);return ApiResponse.success();}}
